const item = $input.first();
const headers = item.json.headers || {};
const body = item.json.body || item.json;
const token = headers['x-webhook-token'];
const expected = $env.N8N_WEBHOOK_SECRET;
if (expected && token !== expected) {
  throw new Error('Invalid webhook token');
}
const e = body;
const t = e.event_type;
let text = '';
if (t === 'signal_event') {
  text = `📊 *Signal* [${e.strategy || ''}]\nMarket: ${e.slug || e.market_id}\nSide: ${e.side} @ ${e.price} (fair ${e.fair_price})\nEdge: ${((e.edge||0)*100).toFixed(1)}%  Conf: ${((e.confidence||0)*100).toFixed(1)}%\nBid/Ask: ${e.bid}/${e.ask}\n${e.reason||''}`;
} else if (t === 'paper_trade_open_event') {
  text = `✅ *Trade Open* #${e.order_id}\nMarket: ${e.market_id}\n${e.side} ${e.size} @ ${e.price}\nQty: ${e.quantity}  Avg: ${e.avg_price}\nUnreal PnL: ${e.unrealized_pnl}\n${e.note||''}`;
} else if (t === 'paper_trade_close_event') {
  text = `🔴 *Trade Close* #${e.order_id}\nMarket: ${e.market_id}\n${e.side} ${e.size} @ ${e.price}\nRealized Δ: ${e.realized_pnl_delta}  Total: ${e.realized_pnl_total}\n${e.note||''}`;
} else if (t === 'risk_alert_event') {
  text = `⚠️ *Risk Alert* (${e.severity})\nMarket: ${e.market_id||'-'}\nReason: ${e.reason}`;
} else if (t === 'daily_report_event') {
  text = `📅 *Daily Report* ${e.report_date}\nStatus: ${e.paused?'⏸️ PAUSED':'🟢 RUNNING'}\nTrades: ${e.total_trades}  Open: ${e.open_positions}  Closed: ${e.closed_positions}\nRealized: ${e.total_realized_pnl}  Unrealized: ${e.total_unrealized_pnl}\nWin/Loss: ${e.winning_positions}/${e.losing_positions}\nExposure: ${e.gross_exposure}`;
} else {
  text = `ℹ️ Unknown event_type=${t}\n${JSON.stringify(e).slice(0,500)}`;
}
return [{ json: { text, event_type: t } }];

const j = $input.first().json;
let endpoint = '/webhook/telegram-command';
let payload = null;
let chatId = null;
let userId = null;
if (j.message && j.message.text) {
  const txt = j.message.text.trim();
  const parts = txt.split(/\s+/);
  const cmd = parts[0].split('@')[0];
  const args = {};
  if (cmd === '/set_mode' && parts[1]) args.mode = parts[1];
  chatId = String(j.message.chat.id);
  userId = String(j.message.from.id);
  payload = { command: cmd, args, user_id: userId, chat_id: chatId };
} else if (j.callback_query) {
  endpoint = '/webhook/telegram-callback';
  chatId = String(j.callback_query.message.chat.id);
  userId = String(j.callback_query.from.id);
  payload = { action: j.callback_query.data, user_id: userId, chat_id: chatId };
} else {
  return [{ json: { skip: true, chatId: null } }];
}
return [{ json: { endpoint, payload, chatId, userId, skip: false } }];

const src = $('Parse Command').first().json;
const resp = $input.first().json;
const chatId = src.chatId;
const cmd = (src.payload && (src.payload.command || src.payload.action)) || 'unknown';
if (!resp || resp.success === false) {
  const err = (resp && resp.error) || 'request failed';
  return [{ json: { chatId, text: `❌ ${cmd}\n${err}` } }];
}
const data = resp.data;
let text = `✅ ${cmd}\n`;
if (cmd === '/status' && data) {
  text += `Mode: ${data.mode}\nPaused: ${data.paused}\nOpen: ${data.open_positions ?? '-'}\nLast tick: ${data.last_tick_at || 'never'}\nError: ${data.last_error || 'none'}`;
} else if ((cmd === '/positions' || cmd === 'POSITIONS') && Array.isArray(data)) {
  if (!data.length) text += '(no positions)';
  else text += data.map(p => `${p.market_id} | qty=${p.quantity} avg=${p.avg_price} u_pnl=${p.unrealized_pnl}`).join('\n');
} else if ((cmd === '/trades' || cmd === 'TRADES') && Array.isArray(data)) {
  if (!data.length) text += '(no trades)';
  else text += data.map(t => `#${t.id} ${t.side} ${t.market_id} ${t.size}@${t.price} [${t.status}]`).join('\n');
} else {
  text += '```\n' + JSON.stringify(data, null, 2).slice(0, 2000) + '\n```';
}
return [{ json: { chatId, text } }];
